const SPHINX = "sphinx";
const SPHINX_BASE_SCORE = 2;
const NO_SCORE = 0;
const TYPES_COVERED_BY_BASE_SCORE = 3;
const SCORE_PER_EXTRA_TYPE = 2;
const SCORE_AT_THE_THRESHOLD = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countOtherMonsterTypes = (army: Card[]): number =>
  new Set(
    army.filter((card) => !isSphinx(card)).map((card) => card.monster),
  ).size;

const scoreBeyondThreeTypes = (otherTypeCount: number): number => {
  const extraTypes = otherTypeCount - TYPES_COVERED_BY_BASE_SCORE;
  return SCORE_AT_THE_THRESHOLD + SCORE_PER_EXTRA_TYPE * extraTypes;
};

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SCORE;

  const otherTypeCount = countOtherMonsterTypes(army);
  if (otherTypeCount > TYPES_COVERED_BY_BASE_SCORE) {
    return scoreBeyondThreeTypes(otherTypeCount);
  }
  return SPHINX_BASE_SCORE;
};
